// Authored pedagogical review of the 2026-09-13 generated lesson snapshot.
// Each row: file id | learning and sequence | exercise assessment / revision | evidence of learning.
export const reviews = {};
function add(course, text) {
  reviews[course] = text.trim().split('\n').map(line => {
    const [id, logic, revision, evidence] = line.split('|').map(s => s.trim());
    if (!evidence) throw new Error(`Incomplete review: ${course} ${id}`);
    return {id:Number(id),logic,revision,evidence};
  });
}

